import json,pathlib,time,numpy as np,onnxruntime as ort
root=pathlib.Path(__file__).parent;data=json.loads((root/'raw-retrieval.json').read_text());opts=ort.SessionOptions();opts.intra_op_num_threads=2;opts.graph_optimization_level=ort.GraphOptimizationLevel.ORT_ENABLE_BASIC
folder=pathlib.Path('laya-onnx-packed');enc=ort.InferenceSession(str(folder/'encoder.onnx'),sess_options=opts);head=ort.InferenceSession(str(folder/'head.onnx'),sess_options=opts);rows=[]
for c,b in zip(data['rows'],data['batches']):
 start=time.perf_counter();mask=np.array(b['attentionMask'],np.int64);hidden=enc.run(None,{'input_ids':np.array(b['inputIds'],np.int64),'attention_mask':mask})[0];logits,act=head.run(None,{'hidden_states':hidden,'marker_pos':np.array(b['markerPos'],np.int64),'marker_mask':np.array(b['markerMask'],np.bool_),'qtype':np.array(b['qtype'],np.int64).reshape(-1,1),'attention_mask':mask});pick=int(logits.argmax());record=c['candidates'][pick] if pick<len(c['candidates']) else None;prob=np.exp(logits-logits.max());prob/=prob.sum()
 rows.append({'id':c['id'],'choice':'NONE' if record is None else chr(65+pick),'record':record,'answer':record['answer'] if record else '지금 질문에는 맞는 답을 찾지 못했어. 상황과 원하는 선택을 조금 더 알려 줘.','probabilities':prob.tolist(),'ms':(time.perf_counter()-start)*1000,'abstentionReason':'Laya returned NONE' if record is None else c['abstentionReason'] if record['id']=='route_unknown' else None})
(root/'raw-laya.json').write_text(json.dumps({'candidateCommit':data['candidateCommit'],'checksum':data['checksum'],'execution':'Python ORT CPU two threads; trained packed encoder/head, same typed shipping candidates and Korean language tokens; no browser execution','rows':rows},ensure_ascii=False,indent=2));print('Saved actual trained-head answers:',len(rows))
